mapper.update:
UPDATE todo SET title=#{title}, description=#{description}, priority=#{priority},
due_date=#{dueDate}, tags=#{tags}, status=#{status}, update_time=NOW()
WHERE id=#{id}

mapper.select:
SELECT * FROM todo WHERE user_id=#{userId}
AND status=#{status}
ORDER BY priority ASC, due_date ASC, create_time DESC

mapper.update:
UPDATE schedule_event SET title=#{title}, description=#{description}, event_type=#{eventType},
start_time=#{startTime}, end_time=#{endTime}, all_day=#{allDay}, color=#{color}
WHERE id=#{id}

mapper.select:
SELECT * FROM schedule_event WHERE user_id=#{userId}
AND start_time >= #{startTime}
AND start_time <= #{endTime}
ORDER BY start_time
